SELECT 'api-integrations', 'service', 'Интеграции и API', 'Связываю 1С, телефонию, мессенджеры и маркетплейсы в единую систему.', '<p>Объединяю разрозненные сервисы: 1С, телефония, мессенджеры, маркетплейсы, платёжные системы. Данные перестают дублироваться, операции ускоряются, отчёты сходятся.</p><h3>Что входит</h3><ul><li>Интеграция с 1С, телефонией, маркетплейсами</li><li>Обмен данными между сервисами</li><li>Платёжные системы и онлайн-кассы</li><li>Вебхуки и API-мосты</li><li>Автоматическая синхронизация остатков и заказов</li><li>Документирование интеграций</li></ul><h3>Частые вопросы</h3><p><strong>Какие интеграции самые частые?</strong><br>Сайт → CRM, CRM → 1С, маркетплейсы → склад, телефония → CRM. Но решаем любые задачи обмена данными между системами.</p>', 25000, 'from', NULL, '🔗', 'piece', 60, 0, 0, 1, 1, 1, '["cash","card","transfer","sbp"]', (SELECT id FROM card_templates WHERE kind = 'service' ORDER BY id LIMIT 1), 1, 160, 'Интеграции и API', 'Связываю 1С, телефонию, мессенджеры и маркетплейсы в единую систему.'
WHERE NOT EXISTS (SELECT 1 FROM services WHERE slug = 'api-integrations');

