INSERT INTO services (slug, kind, title, short_description, full_description, price, price_prefix, price_note, icon, unit, duration_min, booking_enabled, shop_enabled, comments_enabled, rating_enabled, postpay, payment_methods, template_id, active, sort_order, meta_title, meta_description)
SELECT 'messenger-integrations', 'service', 'Telegram/WhatsApp-интеграции', 'Подключаю мессенджеры к отделу продаж: заявки, переписки, рассылки.', '<p>Настраиваю приём заявок и переписку с клиентами прямо в Telegram и WhatsApp: интеграция с сайтом и CRM, уведомления менеджерам, автоответы, рассылки. Продажи едут за клиентом.</p><h3>Что входит</h3><ul><li>Кнопки и виджеты мессенджеров на сайте</li><li>Приём заявок из Telegram/WhatsApp в CRM</li><li>Уведомления менеджерам о новых сообщениях</li><li>Автоответы и сценарии</li><li>Рассылки по базе клиентов</li><li>Интеграция с телефонией</li></ul><h3>Частые вопросы</h3><p><strong>Работает ли это с обычным номером без API?</strong><br>Для полноценной автоматизации нужен доступ к API (Telegram Bot или WhatsApp Business API). Помогаю настроить и пройти верификацию.</p>', 20000, 'from', NULL, '💬', 'piece', 60, 0, 0, 1, 1, 1, '["cash","card","transfer","sbp"]', (SELECT id FROM card_templates WHERE kind = 'service' ORDER BY id LIMIT 1), 1, 170, 'Telegram/WhatsApp-интеграции', 'Подключаю мессенджеры к отделу продаж: заявки, переписки, рассылки.'
WHERE NOT EXISTS (SELECT 1 FROM services WHERE slug = 'messenger-integrations');

-- Аудит и ускорение сайтов
INSERT INTO services (slug, kind, title, short_description, full_description, price, price_prefix, price_note, icon, unit, duration_min, booking_enabled, shop_enabled, comments_enabled, rating_enabled, postpay, payment_methods, template_id, active, sort_order, meta_title, meta_description)
SELECT 'website-speed', 'service', 'Аудит и ускорение сайтов', 'Аудит Core Web Vitals и ускорение загрузки до лидеров ниши.', '<p>Провожу технический аудит и ускоряю сайт: оптимизирую картинки, код, кеширование и хостинг. Быстрый сайт — это больше заявок и выше позиции в поиске.</p><h3>Что входит</h3><ul><li>Аудит Core Web Vitals и PageSpeed</li><li>Оптимизация изображений (WebP/AVIF)</li><li>Кеширование и сжатие</li><li>Оптимизация кода и скриптов</li><li>Ускорение хостинга и CDN</li><li>Контрольный замер после работ</li></ul><h3>Частые вопросы</h3><p><strong>Что такое Core Web Vitals?</strong><br>Это метрики скорости и удобства, которые Google учитывает в ранжировании: скорость загрузки, отзывчивость и стабильность вёрстки. Привожу их в зелёную зону.</p>', 15000, 'from', NULL, '⚡', 'piece', 60, 0, 0, 1, 1, 1, '["cash","card","transfer","sbp"]', (SELECT id FROM card_templates WHERE kind = 'service' ORDER BY id LIMIT 1), 1, 180, 'Аудит и ускорение сайтов', 'Аудит Core Web Vitals и ускорение загрузки до лидеров ниши.'
WHERE NOT EXISTS (SELECT 1 FROM services WHERE slug = 'website-speed');

-- Автоматизация документооборота / RPA
INSERT INTO services (slug, kind, title, short_description, full_description, price, price_prefix, price_note, icon, unit, duration_min, booking_enabled, shop_enabled, comments_enabled, rating_enabled, postpay, payment_methods, template_id, active, sort_order, meta_title, meta_description)
SELECT 'rpa-document', 'service', 'Автоматизация документооборота / RPA', 'Роботы, которые заполняют документы и выполняют рутину за сотрудников.', '<p>Автоматизирую рутинные операции: заполнение документов, перенос данных между системами, обработку вложений почты. Сотрудники перестают заниматься «копипастой», роботы делают это за них.</p><h3>Что входит</h3><ul><li>Автоматизация ввода и переноса данных</li><li>Заполнение и проверка документов</li><li>Обработка входящей почты и вложений</li><li>Интеграция с учётными системами</li><li>Контроль ошибок и логирование</li><li>Оценка эффекта до автоматизации</li></ul><h3>Частые вопросы</h3><p><strong>Что такое RPA простыми словами?</strong><br>RPA — это программные роботы, которые повторяют действия человека в программах: копируют, вставляют, заполняют. Это убирает рутину без замены учётных систем.</p>', NULL, 'none', 'по запросу', '🤖', 'piece', 60, 0, 0, 1, 1, 1, '["cash","card","transfer","sbp"]', (SELECT id FROM card_templates WHERE kind = 'service' ORDER BY id LIMIT 1), 1, 190, 'Автоматизация документооборота / RPA', 'Роботы, которые заполняют документы и выполняют рутину за сотрудников.'
WHERE NOT EXISTS (SELECT 1 FROM services WHERE slug = 'rpa-document');

-- AI-ассистенты для бизнеса
INSERT INTO services (slug, kind, title, short_description, full_description, price, price_prefix, price_note, icon, unit, duration_min, booking_enabled, shop_enabled, comments_enabled, rating_enabled, postpay, payment_methods, template_id, active, sort_order, meta_title, meta_description)
SELECT 'ai-assistants', 'service', 'AI-ассистенты для бизнеса', 'Персональные AI-помощники для продаж, поддержки и внутренних процессов.', '<p>Создаю AI-ассистентов, которые работают в вашей команде: отвечают клиентам, готовят коммерческие предложения, анализируют обращения, помогают менеджерам. Это как дополнительный сотрудник без зарплаты.</p><h3>Что входит</h3><ul><li>Ассистент отдела продаж</li><li>AI-поддержка клиентов 24/7</li><li>Генерация КП, писем и контента</li><li>Анализ обращений и настроений</li><li>Интеграция с CRM и мессенджерами</li><li>Обучение на ваших данных</li></ul><h3>Частые вопросы</h3><p><strong>AI будет выдавать неточности?</strong><br>Качество зависит от настройки: ограничиваю модель вашей базой знаний, добавляю проверки и человека в цикле для ответственных операций. Результат контролируем.</p>', 60000, 'from', NULL, '🧠', 'piece', 60, 0, 0, 1, 1, 1, '["cash","card","transfer","sbp"]', (SELECT id FROM card_templates WHERE kind = 'service' ORDER BY id LIMIT 1), 1, 200, 'AI-ассистенты для бизнеса', 'Персональные AI-помощники для продаж, поддержки и внутренних процессов.'
WHERE NOT EXISTS (SELECT 1 FROM services WHERE slug = 'ai-assistants');
